## 3. Result-Generation Logic (form data → recommendation)

The core recommendation logic lives inline in the Compass page as the `evaluate()` function (TypeScript), not in a separate lib file. `pdfExport.ts` is only the shared PDF/HTML rendering helper. Both are included verbatim below.

Source: `client/src/pages/TESECompass.tsx`

```typescript
type AzoType = "obstructive" | "non_obstructive" | "unknown";
type KaryotypeResult = "normal" | "klinefelter" | "y_deletion_azfa" | "y_deletion_azfb" | "y_deletion_azfc" | "other" | "not_done";

interface TESEInputs {
  azoospermiaType: AzoType;
  fshLevel: number;
  lhLevel: number;
  testosteroneLevel: number;
  inhibinB: number;
  testisVolume: "normal" | "reduced" | "atrophic";
  karyotype: KaryotypeResult;
  cftrMutation: boolean;
  priorTESE: boolean;
  priorTESEResult: "sperm_found" | "no_sperm" | "not_done";
  histologyAvailable: boolean;
  histologyPattern: "normal" | "hypospermatogenesis" | "maturation_arrest" | "sertoli_only" | "not_done";
  partnerAge: number;
  oncologyPatient: boolean;
}

const defaultInputs: TESEInputs = {
  azoospermiaType: "non_obstructive", fshLevel: 0, lhLevel: 0, testosteroneLevel: 0,
  inhibinB: 0, testisVolume: "reduced", karyotype: "not_done", cftrMutation: false,
  priorTESE: false, priorTESEResult: "not_done", histologyAvailable: false,
  histologyPattern: "not_done", partnerAge: 0, oncologyPatient: false,
};

function evaluate(inputs: TESEInputs) {
  const warnings: string[] = [];
  const rationale: string[] = [];
  const references = [
    "Schlegel PN. Testicular sperm extraction: microdissection improves sperm yield with minimal tissue excision. Hum Reprod. 1999;14(1):131-135.",
    "Bernie AM, et al. Predictive factors of successful microdissection testicular sperm extraction in men with non-obstructive azoospermia. J Urol. 2015;194(6):1685-1689.",
    "Esteves SC, et al. Reproductive outcomes of testicular versus ejaculated sperm for intracytoplasmic sperm injection among men with high sperm DNA fragmentation in semen: systematic review and meta-analysis. Fertil Steril. 2017;108(3):456-467.",
    "Wosnitzer MS, Goldstein M. Obstructive azoospermia. Urol Clin North Am. 2014;41(1):83-95.",
    "Practice Committee of the American Society for Reproductive Medicine. The management of infertility due to obstructive azoospermia. Fertil Steril. 2019;111(5):873-880.",
  ];

  let recommendation = "not_indicated";
  let procedure = "";
  let cor = "I";
  let loe = "B";
  let successRate = "";

  if (inputs.azoospermiaType === "obstructive") {
    recommendation = "indicated";
    procedure = "Conventional TESE or PESA/MESA (obstructive azoospermia)";
    cor = "I"; loe = "A";
    successRate = "~90–100% sperm retrieval";
    rationale.push("Obstructive azoospermia: sperm retrieval rates are very high (90–100%) with PESA, MESA, or conventional TESE.");
    rationale.push("PESA (percutaneous epididymal sperm aspiration) is minimally invasive and preferred first approach.");
  } else if (inputs.azoospermiaType === "non_obstructive") {
    // micro-TESE for NOA
    recommendation = "indicated";
    procedure = "Microdissection TESE (micro-TESE) — preferred for NOA";
    cor = "I"; loe = "B";

    // Predict success rate based on histology and hormones
    if (inputs.histologyPattern === "hypospermatogenesis") {
      successRate = "~70–80% sperm retrieval";
      rationale.push("Hypospermatogenesis pattern: highest micro-TESE success rate (~70–80%).");
    } else if (inputs.histologyPattern === "maturation_arrest") {
      successRate = "~30–50% sperm retrieval";
      rationale.push("Maturation arrest: moderate success rate (~30–50%) with micro-TESE.");
    } else if (inputs.histologyPattern === "sertoli_only") {
      successRate = "~15–30% sperm retrieval";
      rationale.push("Sertoli cell-only (SCO) pattern: lower success rate (~15–30%) but micro-TESE remains the best option.");
    } else {
      successRate = "~40–60% sperm retrieval (estimated)";
      rationale.push("Micro-TESE (Schlegel 1999) improves sperm retrieval by 1.5× over conventional TESE in NOA through direct visualization of spermatogenic foci.");
    }

    // AZF deletions
    if (inputs.karyotype === "y_deletion_azfa" || inputs.karyotype === "y_deletion_azfb") {
      recommendation = "not_indicated";
      procedure = "TESE NOT recommended — AZFa or AZFb deletion";
      warnings.push("Complete AZFa or AZFb deletion: sperm retrieval is virtually impossible (<1%). TESE is not recommended. Donor sperm should be discussed.");
      cor = "III"; loe = "A";
    } else if (inputs.karyotype === "y_deletion_azfc") {
      warnings.push("AZFc deletion: sperm retrieval possible in ~50–70% of cases. Genetic counseling required — 50% of male offspring will inherit deletion.");
    } else if (inputs.karyotype === "klinefelter") {
      successRate = "~40–60% sperm retrieval";
      warnings.push("Klinefelter syndrome (47,XXY): micro-TESE success ~40–60%. Testosterone supplementation should be stopped 3–6 months pre-operatively.");
      rationale.push("Klinefelter syndrome: micro-TESE is the preferred approach; conventional TESE has significantly lower yield.");
    }
  }

  if (inputs.fshLevel > 20) {
    warnings.push(`Markedly elevated FSH (${inputs.fshLevel} mIU/mL): suggests severe spermatogenic impairment; however, FSH alone cannot exclude sperm retrieval.`);
  }
  if (inputs.inhibinB < 40 && inputs.inhibinB > 0) {
    warnings.push(`Low inhibin B (${inputs.inhibinB} pg/mL): associated with reduced sperm retrieval rates in NOA.`);
  }
  if (inputs.partnerAge > 37) {
    warnings.push(`Partner age ${inputs.partnerAge}: time-sensitive — expedite evaluation and procedure planning.`);
  }
  if (inputs.oncologyPatient) {
    warnings.push("Oncology patient: sperm cryopreservation is urgent — perform before gonadotoxic therapy. Coordinate with oncology team.");
    rationale.push("ASCO guidelines recommend fertility preservation counseling and sperm banking before any gonadotoxic therapy.");
  }
  if (inputs.priorTESE && inputs.priorTESEResult === "no_sperm") {
    warnings.push("Prior TESE with no sperm found: repeat micro-TESE may still yield sperm in 20–30% of cases; refer to high-volume center.");
  }

  return { recommendation, procedure, successRate, cor, loe, warnings, rationale, references };
}
